"""Revocation epoch check for cached sessions."""


class Session:
    def __init__(self, subject, epoch):
        self.subject = subject
        self.epoch = epoch


class RevocationState:
    def __init__(self, subject, epoch, settled):
        self.subject = subject
        self.epoch = epoch
        self.settled = settled


